CREATE TABLE IF NOT EXISTS inquiries (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT,project_type TEXT NOT NULL,message TEXT,created_at TEXT NOT NULL,ip_hash TEXT); CREATE TABLE IF NOT EXISTS inquiry_rate (id INTEGER PRIMARY KEY AUTOINCREMENT,ip TEXT NOT NULL,ts INTEGER NOT NULL); CREATE INDEX IF NOT EXISTS inquiry_rate_ip_ts ON inquiry_rate(ip,ts);